import sys

def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    A, B = map(int, input_data.split())
    K = (A + B) // 2
    # Since A and B are distinct integers, their sum is odd if they have different parity,
    # making (A+B)/2 a non-integer. In that case, no integer K exists.
    if (A + B) % 2 != 0:
        print("IMPOSSIBLE")
    else:
        print(K)

if __name__ == "__main__":
    solve()
